on conflict (slug) do update set
  titulo = excluded.titulo,
  subtitulo = excluded.subtitulo,
  tipo = excluded.tipo,
  ordem = excluded.ordem,
  dados = jsonb_set(
    excluded.dados,
    '{abas}',
    (excluded.dados->'abas') || coalesce(
      (select jsonb_agg(a) from jsonb_array_elements(c.dados->'abas') a where a->>'tipo' = 'cartoes'),
      '[]'::jsonb
    )
  );

